    'nunique': np.unique,
    'rms': np.sqrt(np.var)
}

# Define the rank function
def rank_rows(df, direction='max'):
    if direction == 'max':
        return df.groupby('record_id')['MLII'].rank(method='dense', ascending=False)
    elif direction == 'min':
        return df.groupby('record_id')['MLII'].rank(method='dense', ascending=True)
    else:
