# Define the derive_binary function
def derive_binary(df, left, right, operation):
    if operation == 'add':
        return df.apply(lambda x: x + y, axis=1)
    elif operation == 'subtract':
        return df.apply(lambda x: x - y, axis=1)
    elif operation == 'multiply':
        return df.apply(lambda x: x * y, axis=1)
    elif operation == 'divide':
        return df.apply(lambda x: x / y, axis=1)
    elif operation == 'abs_difference':
        return df.apply(lambda x: np.abs(x - y), axis=1)
    else:
